  "estimatedLines": 51,
  "evidence": {
    "aspects": [
      {
        "aspectIndex": 0,
        "criterionId": "q1",
        "earned": true,
        "quote": "Em 1920, São Paulo urbanizava-se e expandia-se rapidamente, com o surto industrial ocorrido nos anos da 1ª Guerra Mundial e a imigração em massa."
      },
      {
        "aspectIndex": 1,
        "criterionId": "q1",
        "earned": true,
        "quote": "A economia cafeeira permitiu a injeção de capitais em infraestrutura e serviços urbanos, e a expansão do comércio."
      },
      {
        "aspectIndex": 2,
        "criterionId": "q1",
        "earned": false,
        "quote": null
      },
      {
        "aspectIndex": 3,
        "criterionId": "q2",
        "earned": true,
        "quote": "políticos e intelectuais como Anita Malfatti, Tarsila do Amaral, Oswald e Mário de Andrade, Paulo Prado, Menotti del Picchia e Villa Lobos."
      },
      {
        "aspectIndex": 4,
        "criterionId": "q2",
        "earned": true,
        "quote": "o artigo “Paranóia ou Mistificação?” de Monteiro Lobato contra a exposição de Malfatti, no jornal O Estado de S. Paulo."
      },
      {
        "aspectIndex": 5,
        "criterionId": "q2",
        "earned": true,
        "quote": "São Paulo estava afastada das “novidades” da capital, mas buscava protagonismo e voz própria com o modernismo, que busca conectar-se ao mundo e, também, ao contexto local."
      },
      {
        "aspectIndex": 6,
        "criterionId": "q3",
        "earned": true,
        "quote": "O movimento modernista consolidou-se na década de 1920, a partir da crítica ao parnasianismo e ao simbolismo e da reivindicação da nacionalidade e da “cor local”."
      },
      {
        "aspectIndex": 7,
        "criterionId": "q3",
        "earned": true,
        "quote": "Anita Malfatti, Tarsila do Amaral, Oswald e Mário de Andrade"
      },
      {
        "aspectIndex": 8,
        "criterionId": "q3",
        "earned": true,
        "quote": "predominavam em São Paulo o academicismo dos conservatórios e das escolas de belas artes, e a elite cultivava as formas neoclássicas do século XIX nas artes, por influência da AIBA e da Academia Brasileira de Letras, permeada pelo Arcadismo e Parnasianismo."
      },
      {
        "aspectIndex": 9,
        "criterionId": "q4",
        "earned": true,
        "quote": "em 13 de fevereiro de 1922, no Theatro Municipal, a Semana de Arte Moderna"
      },
      {
        "aspectIndex": 10,
        "criterionId": "q4",
        "earned": true,
        "quote": "no Theatro Municipal"
      },
      {
        "aspectIndex": 11,
        "criterionId": "q4",
        "earned": true,
        "quote": "Os três dias de programação incluíram a declamação de poesias (“Os Sapos”, de Manuel Bandeira), exposições (“O Homem Amarelo”, de Malfatti), e apresentações de piano de Villa Lobos e Guiomar Novaes."
      },
      {
        "aspectIndex": 12,
        "criterionId": "q5",
        "earned": true,
        "quote": "Tematizou-se a questão racial no Brasil, a incorporação da modernidade e a rejeição ao academicismo, as vanguardas europeias (cubismo, futurismo, expressionismo), e a questão regional, sem, contudo, reivindicar pautas políticas específicas."
      },
      {
        "aspectIndex": 13,
        "criterionId": "q5",
        "earned": true,
        "quote": "Tematizou-se a questão racial no Brasil, a incorporação da modernidade"
      },
      {
        "aspectIndex": 14,
