      },
      {
        "aspectIndex": 3,
        "criterionId": "q2",
        "earned": true,
        "quote": "A diplomacia é essencial não só para promover a arte brasileira, mas também para incentivar a humanização das relações internacionais."
      },
      {
        "aspectIndex": 4,
        "criterionId": "q2",
        "earned": true,
